-- ----------------------------------------------------------------------------
-- LanguageCandidates: Table: LanguageCandidates
-- ----------------------------------------------------------------------------
CREATE TABLE language_candidates (
  language_candidate_id               TEXT                 PRIMARY KEY,
  name                                TEXT                ,                     -- Name of the language candidate being classified.
  is_language                         BOOLEAN             ,                     -- The test answer that is intended to match the Family Feud answer to be "correct".
  has_syntax                          BOOLEAN             ,                     -- Does this language candidate have syntax and/or grammar?
  can_be_held                         BOOLEAN             ,                     -- Is this candidate physical/material.  I.e. could it at least theoretically "be held"?
  category                            TEXT                ,                     -- The general high level category of the candidate.
  has_identity                        BOOLEAN             ,                     -- Could this thing be assigned a guid, unique in the universe that would identify it globally?  Like a drivers license or social security number for a person.
  is_parsed                           BOOLEAN             ,                     -- Is the knowledge/information encoded in a form that requires parsing before meaning can be extracted?
  resolves_to_an_ast                  BOOLEAN             ,                     -- Is the knowledge/information encoded in a form that requires parsing before meaning can be extracted?
  has_linear_decoding_pressure        BOOLEAN             ,
  is_stable_ontology_reference        BOOLEAN             ,
  is_live_ontology_editor             BOOLEAN             ,
  is_open_world                       BOOLEAN             ,
  is_closed_world                     BOOLEAN             ,
  distance_from_concept               INTEGER             ,
  dimensionality_while_editing        TEXT                ,
  model_object_facility_layer         TEXT                ,
  sort_order                          INTEGER             
);
COMMENT ON TABLE language_candidates IS 'Table: LanguageCandidates';
COMMENT ON COLUMN language_candidates.name IS 'Name of the language candidate being classified.';
COMMENT ON COLUMN language_candidates.is_language IS 'The test answer that is intended to match the Family Feud answer to be "correct".';
COMMENT ON COLUMN language_candidates.has_syntax IS 'Does this language candidate have syntax and/or grammar?';
COMMENT ON COLUMN language_candidates.can_be_held IS 'Is this candidate physical/material.  I.e. could it at least theoretically "be held"?';
COMMENT ON COLUMN language_candidates.category IS 'The general high level category of the candidate.';
COMMENT ON COLUMN language_candidates.has_identity IS 'Could this thing be assigned a guid, unique in the universe that would identify it globally?  Like a drivers license or social security number for a person.';
COMMENT ON COLUMN language_candidates.is_parsed IS 'Is the knowledge/information encoded in a form that requires parsing before meaning can be extracted?';
COMMENT ON COLUMN language_candidates.resolves_to_an_ast IS 'Is the knowledge/information encoded in a form that requires parsing before meaning can be extracted?';

