-- ----------------------------------------------------------------------------
-- HockettFeatures: Table: HockettFeatures
-- ----------------------------------------------------------------------------
CREATE TABLE hockett_features (
  hockett_feature_id                  TEXT                 PRIMARY KEY,
  name                                TEXT                ,                     -- The design feature's name, as Hockett gives it.
  feature_number                      INTEGER             ,                     -- Hockett's own numbering, 1 through 13, then 14 through 16 for the 1968 additions.
  definition                          TEXT                ,                     -- What the feature asserts, in plain English.
  is_original_thirteen                BOOLEAN             ,                     -- TRUE for the thirteen features of the 1960 paper; FALSE for the three added in 1968.
  source                              TEXT                                      -- Citation for the feature list.
);
COMMENT ON TABLE hockett_features IS 'Table: HockettFeatures';
COMMENT ON COLUMN hockett_features.name IS 'The design feature''s name, as Hockett gives it.';
COMMENT ON COLUMN hockett_features.feature_number IS 'Hockett''s own numbering, 1 through 13, then 14 through 16 for the 1968 additions.';
COMMENT ON COLUMN hockett_features.definition IS 'What the feature asserts, in plain English.';
COMMENT ON COLUMN hockett_features.is_original_thirteen IS 'TRUE for the thirteen features of the 1960 paper; FALSE for the three added in 1968.';
COMMENT ON COLUMN hockett_features.source IS 'Citation for the feature list.';

-- ----------------------------------------------------------------------------
-- HockettAssessments: Table: HockettAssessments
-- ----------------------------------------------------------------------------
CREATE TABLE hockett_assessments (
  hockett_assessment_id               TEXT                 PRIMARY KEY,
  language_candidate                  TEXT                ,                     -- FK to the candidate being assessed.
  hockett_feature                     TEXT                ,                     -- FK to the design feature being applied.
  verdict                             TEXT                ,                     -- Yes, No, Partial or Unknown. Partial and Unknown exist because the published assessments hedge, and flattening a hedge into a boolean would bury a judgement call in the data.
  verbatim_assessment                 TEXT                ,                     -- The source's exact wording for this cell, so every resolution to Verdict stays auditable.
  source_citation                     TEXT                ,                     -- Where this cell came from, including which column.
  mapping_note                        TEXT                                      -- Empty when this candidate corresponds exactly to the source's column. Otherwise, how the two differ and how far the row should be trusted.
);
COMMENT ON TABLE hockett_assessments IS 'Table: HockettAssessments';
COMMENT ON COLUMN hockett_assessments.language_candidate IS 'FK to the candidate being assessed.';
COMMENT ON COLUMN hockett_assessments.hockett_feature IS 'FK to the design feature being applied.';
COMMENT ON COLUMN hockett_assessments.verdict IS 'Yes, No, Partial or Unknown. Partial and Unknown exist because the published assessments hedge, and flattening a hedge into a boolean would bury a judgement call in the data.';
COMMENT ON COLUMN hockett_assessments.verbatim_assessment IS 'The source''s exact wording for this cell, so every resolution to Verdict stays auditable.';
COMMENT ON COLUMN hockett_assessments.source_citation IS 'Where this cell came from, including which column.';
COMMENT ON COLUMN hockett_assessments.mapping_note IS 'Empty when this candidate corresponds exactly to the source''s column. Otherwise, how the two differ and how far the row should be trusted.';

